mapper.sql:
EXISTS (
    SELECT 1
    FROM auth_principal principal
    JOIN auth_principal_role_assignment role_assignment
      ON role_assignment.principal_id = principal.principal_id
    JOIN auth_role_capability role_capability
      ON role_capability.role_id = role_assignment.role_id
    JOIN auth_capability granted_capability
      ON granted_capability.capability_id =
         role_capability.capability_id
     AND granted_capability.capability_code = #{capability}
    JOIN auth_data_scope data_scope
      ON data_scope.scope_id = role_assignment.data_scope_id
     AND data_scope.scope_type = 'COMPANY'
     AND data_scope.company_id = source.company_id
    WHERE principal.principal_id = #{principalId}
      AND principal.status = 'ACTIVE'
      AND role_assignment.valid_from <= #{authorizationTime}
      AND (
            role_assignment.valid_to IS NULL
            OR role_assignment.valid_to > #{authorizationTime}
      )
      AND data_scope.valid_from <= #{authorizationTime}
      AND (
            data_scope.valid_to IS NULL
            OR data_scope.valid_to > #{authorizationTime}
      )
)

