SELECT attendance_ingestion_idempotency_id AS idempotency_id,
       request_digest,
       status,
       JSON_UNQUOTE(
           JSON_EXTRACT(response_body_json, '$.jobId')
       ) AS replay_job_id
FROM attendance_ingestion_idempotency
WHERE actor_id = #{principalId}
  AND operation_code = 'DELI_SOURCE_RETRY'
  AND resource_type = 'ATTENDANCE_SYNC_JOB'
  AND resource_id = #{originalJobId}
  AND idempotency_key = #{idempotencyKey}
FOR UPDATE

mapper.update:
UPDATE attendance_sync_job
SET row_version = row_version + 1
WHERE attendance_sync_job_id = #{originalJobId}
  AND row_version = #{expectedRowVersion}
  AND status IN ('FAILED', 'PARTIALLY_QUARANTINED', 'CANCELLED')

